/** The permutation, its first 256 entries (D3DX repeats them), as the DLL holds it: p[253] repeats p[0]'s 0. */
export const NOISE_P = [0,1,109,3,175,5,24,7,178,236,37,240,149,13,152,15,17,198,190,22,225,130,19,23,195,25,74,27,85,29,66,31,191,33,188,254,14,166,233,120,235,41,28,144,40,45,21,47,205,248,8,110,163,53,105,55,154,57,71,59,244,212,16,174,177,65,183,156,84,69,185,168,119,88,11,158,96,170,62,79,121,81,67,83,199,160,136,87,210,134,36,91,242,93,161,164,18,232,241,216,56,101,51,103,189,54,138,107,252,202,102,111,122,113,48,115,72,228,58,226,39,184,89,123,135,125,100,127,82,129,46,131,157,133,148,196,181,137,108,139,237,141,90,143,43,145,187,147,142,12,238,192,180,153,75,155,176,132,222,186,42,94,116,230,95,165,194,167,118,169,77,171,80,173,63,4,128,64,140,60,112,86,124,30,34,70,159,146,224,104,10,32,151,193,76,246,182,197,78,206,44,201,2,203,249,150,250,207,234,209,73,211,61,213,251,215,99,217,26,219,50,221,126,223,172,208,106,227,117,229,52,231,97,38,20,200,9,220,114,239,218,98,6,243,179,245,92,247,49,204,68,214,162,0,35,255];
/** The gradients, unit vectors x, y, z: Perlin's init() on MSVC's rand() (seed 1), each drawn by rejection. */
export const NOISE_G = (() => {
  let x = 1;
  const rand = () => ((x = (Math.imul(x, 214013) + 2531011) >>> 0) >>> 16) & 0x7fff;
  const g = [];
  for (let i = 0; i < 256; i++) {
    let v, l;
    do { v = [0, 1, 2].map(() => ((rand() % 512) - 256) / 256); l = v[0] * v[0] + v[1] * v[1] + v[2] * v[2]; } while (!(l > 0 && l <= 1));
    const s = Math.sqrt(l);
    g.push(...v.map((c) => Math.fround(c / s)));
  }
  return g;
})();
